class Solution {
public:
    int minOperations(std::vector<int>& nums, std::vector<int>& numsDivide) {
        int g = numsDivide[0];
        for (int x : numsDivide) g = std::gcd(g, x);
        std::sort(nums.begin(), nums.end());
        for (size_t i = 0; i < nums.size(); ++i) {
            if (g % nums[i] == 0) return i;
        }
        return -1;
    }
};

class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        int g = numsDivide[0];
        for (int x : numsDivide) g = gcd(g, x);
        java.util.Arrays.sort(nums);
        for (int i = 0; i < nums.length; ++i) {
            if (g % nums[i] == 0) return i;
        }
        return -1;
    }
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

var minOperations = function(nums, numsDivide) {
    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
    let g = numsDivide[0];
    for (const x of numsDivide) g = gcd(g, x);
    nums.sort((a, b) => a - b);
    for (let i = 0; i < nums.length; ++i) {
        if (g % nums[i] === 0) return i;
    }
    return -1;
};
